import sys
import json
import os
import xml.etree.ElementTree as ET
from pathlib import Path

def parse_config_file(config_path):
    try:
        tree = ET.parse(config_path)
        root = tree.getroot()
        mapping = {}
        for entry in root.findall('entry'):
            key = entry.get('key')
            value = entry.get('value')
            if key and value:
                mapping[key] = value
        return mapping
    except Exception as e:
        sys.stderr.write(f"error: {config_path}\n")
        sys.exit(1)

def get_cache_path(config_path):
    return config_path.with_suffix('.cache')

def get_modification_time(file_path):
    return os.path.getmtime(file_path)

def load_cache(cache_path):
    try:
        with open(cache_path, 'r') as f:
            return json.load(f)
    except Exception as e:
        sys.stderr.write(f"error: {cache_path}\n")
        sys.exit(1)

def save_cache(cache_path, mapping):
    try:
        with open(cache_path, 'w') as f:
            json.dump(mapping, f, indent=2)
    except Exception as e:
        sys.stderr.write(f"error: {cache_path}\n")
        sys.exit(1)

def main():
    if len(sys.argv) != 2:
        sys.stderr.write("Usage: python settings_viewer.py <config.xml>\n")
        sys.exit(1)

    config_path = sys.argv[1]
    cache_path = get_cache_path(config_path)

    try:
        config_time = get_modification_time(config_path)
        cache_time = get_modification_time(cache_path) if os.path.exists(cache_path) else -1

        if cache_time >= config_time:
            mapping = load_cache(cache_path)
            source = 'cache'
        else:
            mapping = parse_config_file(config_path)
            save_cache(cache_path, mapping)
            source = 'xml'

        sys.stderr.write(f"source={source}\n")
        print(json.dumps(mapping, indent=2))
    except Exception:
        sys.stderr.write(f"error: {config_path}\n")
        sys.exit(1)

if __name__ == "__main__":
    main()

