import sys
import json
import xml.etree.ElementTree as ET
from pathlib import Path

def parse_xml_to_dict(xml_path):
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
        entries = root.findall('entry')
        return {entry.attrib['key']: entry.attrib['value'] for entry in entries}
    except Exception as e:
        print(f"error: {xml_path}", file=sys.stderr)
        sys.exit(1)

def read_cache(cache_path):
    try:
        with open(cache_path, 'r') as f:
            return json.load(f)
    except Exception as e:
        print(f"error: {cache_path}", file=sys.stderr)
        sys.exit(1)

def write_cache(cache_path, data):
    try:
        with open(cache_path, 'w') as f:
            json.dump(data, f, indent=2)
    except Exception as e:
        print(f"error: {cache_path}", file=sys.stderr)
        sys.exit(1)

def main():
    xml_path = sys.argv[1]
    cache_path = Path(xml_path).with_suffix('.cache')

    if cache_path.exists():
        print(json.dumps(read_cache(cache_path)), file=sys.stdout)
        print("source=cache", file=sys.stderr)
    else:
        data = parse_xml_to_dict(xml_path)
        write_cache(cache_path, data)
        print(json.dumps(data, indent=2), file=sys.stdout)
        print("source=xml", file=sys.stderr)

if __name__ == "__main__":
    main()

