import sys
import os
import json
import xml.etree.ElementTree as ET

def load_settings(config_path):
    cache_path = config_path + '.cache'
    if os.path.exists(cache_path):
        try:
            with open(cache_path, 'r') as cache_file:
                return json.load(cache_file), 'cache'
        except Exception:
            print(f'error: {cache_path}', file=sys.stderr)
            sys.exit(1)
    else:
        try:
            tree = ET.parse(config_path)
            root = tree.getroot()
            settings_dict = {entry.get('key'): entry.get('value') for entry in root.findall('entry')}
            with open(cache_path, 'w') as cache_file:
                json.dump(settings_dict, cache_file)
            return settings_dict, 'xml'
        except Exception:
            print(f'error: {config_path}', file=sys.stderr)
            sys.exit(1)

if __name__ == '__main__':
    if len(sys.argv) != 2:
        print('Usage: python settings_viewer.py <config.xml>', file=sys.stderr)
        sys.exit(1)
    config_path = sys.argv[1]
    settings, source = load_settings(config_path)
    print(json.dumps(settings, indent=2) + '\n')
    print(f'source={source}', file=sys.stderr)
